package com.coraline.feast;

import com.coraline.otherworld.*;
import com.coraline.secrets.*;
import net.minecraft.core.*;
import net.minecraft.core.registries.Registries;
import net.minecraft.nbt.*;
import net.minecraft.server.level.*;
import net.minecraft.tags.BlockTags;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.properties.*;
import net.minecraft.world.phys.AABB;
import java.util.*;

/** Incremental terrain A* and reversible, batched paths/cottages. No fixed global destination. */
final class DeliveryRoute {
    private record Step(BlockPos at,double priority){}
    private static final class Search {
        final PriorityQueue<Step> open=new PriorityQueue<>(Comparator.comparingDouble(Step::priority));
        final Map<BlockPos,BlockPos> back=new HashMap<>();final Map<BlockPos,Double> cost=new HashMap<>();
        final BlockPos start,goal;int expanded;
        Search(BlockPos start,BlockPos goal){this.start=start;this.goal=goal;back.put(start,start);cost.put(start,0.);open.add(new Step(start,start.distManhattan(goal)));}
    }
    private static final Map<UUID,Search> SEARCHES=new HashMap<>();
    static BlockPos house(VisitData.Scene s){return s.loop.event.contains("DeliveryHouse")?BlockPos.of(s.loop.event.getLong("DeliveryHouse")):null;}
    static BlockPos door(VisitData.Scene s){var house=house(s);return house==null?null:house.north(4);}
    static List<BlockPos> nodes(VisitData.Scene s){return Arrays.stream(s.loop.event.getLongArray("DeliveryRoute")).mapToObj(BlockPos::of).toList();}
    static boolean prepare(ServerPlayer p,VisitData.Scene s){var r=SecretWorld.realm(p);if(r==null||r.house==null||r.porch==null)return false;var n=s.loop.event;int attempt=n.getInt("RouteAttempt");if(attempt>=18)return false;var random=new Random(n.getLong("DeliverySeed")+attempt*7919);BlockPos c=null;
        for(int i=0;i<20;i++){double angle=random.nextDouble()*Math.PI*2,distance=120+random.nextInt(121);int x=r.house.getX()+(int)(Math.cos(angle)*distance),z=r.house.getZ()+(int)(Math.sin(angle)*distance);if(!p.serverLevel().hasChunkAt(new BlockPos(x,r.house.getY(),z)))continue;var probe=OutingSites.surface(p.serverLevel(),x,z);if(probe==null||!OutingSites.copied(r,probe)||OtherWorldEstate.outsideDistance(r.house,probe)<35||SecretDialogue.secretArea(s.loop.secrets,probe))continue;if(SecretWorld.rooms(s.loop.secrets).stream().anyMatch(room->BlockPos.of(room.getLong("Pos")).distSqr(probe)<30*30))continue;if(!cottageSpace(p.serverLevel(),r,s,probe))continue;c=probe;break;}
        n.putInt("RouteAttempt",attempt+1);if(c==null)return true;BlockPos start=r.porch;if(!OutingSites.feet(p.serverLevel(),start)){start=null;for(int radius=1;radius<=12&&start==null;radius++)for(int x=-radius;x<=radius&&start==null;x++)for(int z=-radius;z<=radius;z++){var q=OutingSites.surface(p.serverLevel(),r.porch.getX()+x,r.porch.getZ()+z);if(q!=null){start=q;break;}}}if(start==null)return false;
        n.putLong("DeliveryHouse",c.asLong());n.putLong("RouteStart",start.asLong());n.putLong("RouteGoal",c.north(6).asLong());SEARCHES.put(p.getUUID(),new Search(start,c.north(6)));return true;
    }
    static boolean cottageSpace(ServerLevel l,RealmData.Realm r,VisitData.Scene s,BlockPos c){for(int x=-6;x<=6;x++)for(int z=-7;z<=6;z++){var p=c.offset(x,0,z);var surface=OutingSites.surface(l,p.getX(),p.getZ());if(surface==null||Math.abs(surface.getY()-c.getY())>2||!OutingSites.copied(r,p)||SecretDialogue.secretArea(s.loop.secrets,p)||!OutingSites.natural(l,surface))return false;for(int y=-2;y<11;y++){var at=p.above(y);var state=l.getBlockState(at);if(state.hasBlockEntity()||!state.isAir()&&!state.is(BlockTags.FLOWERS)&&!state.is(BlockTags.LEAVES)&&!state.is(BlockTags.LOGS)&&!state.is(BlockTags.DIRT)&&!state.is(BlockTags.BASE_STONE_OVERWORLD)&&!state.is(Blocks.GRASS)&&!state.is(Blocks.TALL_GRASS)&&!state.is(Blocks.SAND)&&!state.is(Blocks.GRAVEL))return false;}}return OutingSites.feet(l,c.north(6));}
    static boolean ready(VisitData.Scene s){return s.loop.story.getCompound("PreparedDeliveryRoute").getBoolean("Ready");}
    /** Plan without changing the world or acquiring chunk leases during another event. */
    static void prewarm(ServerPlayer p,VisitData.Scene s){
        if(!OtherWorld.isOther(p.level())||VisitEvents.type(s)==VisitEvents.Type.SPECIAL_DELIVERY||BlackIsTraditional.active(s))return;var r=SecretWorld.realm(p);if(r==null||r.house==null||r.porch==null)return;
        var n=s.loop.story.getCompound("PreparedDeliveryRoute");if(n.getBoolean("Ready")&&n.getLong("HouseAnchor")==r.house.asLong()||OtherMotherLoop.now(p)<n.getLong("RetryAt"))return;
        if(!n.contains("HouseAnchor")||n.getLong("HouseAnchor")!=r.house.asLong()){SEARCHES.remove(p.getUUID());n=new CompoundTag();n.putLong("HouseAnchor",r.house.asLong());n.putLong("DeliverySeed",p.getRandom().nextLong());n.putBoolean("PlanningOnly",true);s.loop.story.put("PreparedDeliveryRoute",n);}
        var planning=new VisitData.Scene();planning.owner=s.owner;planning.door=s.door;planning.table=s.table;planning.piano=s.piano;planning.loop.secrets=s.loop.secrets;planning.loop.event=n;
        String status=tick(p,planning);if(status.equals("READY")){n.putBoolean("Ready",true);OtherMotherLoop.changed(p);}else if(status.equals("FAILED")){SEARCHES.remove(p.getUUID());n=new CompoundTag();n.putLong("RetryAt",OtherMotherLoop.now(p)+600);s.loop.story.put("PreparedDeliveryRoute",n);OtherMotherLoop.changed(p);}
    }
    static boolean activatePrepared(ServerPlayer p,VisitData.Scene s){
        if(!ready(s))return false;var plan=s.loop.story.getCompound("PreparedDeliveryRoute");var r=SecretWorld.realm(p);var points=Arrays.stream(plan.getLongArray("DeliveryRoute")).mapToObj(BlockPos::of).toList();
        if(r==null||r.house==null||plan.getLong("HouseAnchor")!=r.house.asLong()){s.loop.story.remove("PreparedDeliveryRoute");return false;}
        EventChunks.hold(p,s,points);BlockPos destination=BlockPos.of(plan.getLong("DeliveryHouse"));
        if(points.isEmpty()||!cottageSpace(p.serverLevel(),r,s,destination)||points.stream().anyMatch(at->!OutingSites.feet(p.serverLevel(),at)||SecretDialogue.secretArea(s.loop.secrets,at))){s.loop.story.remove("PreparedDeliveryRoute");return false;}
        for(String key:List.of("DeliverySeed","DeliveryHouse","DeliveryRoute","RouteStart","RouteGoal","RouteAttempt")){var value=plan.get(key);if(value!=null)s.loop.event.put(key,value.copy());}
        // Snapshot originals again at activation, not from an earlier exploration minute.
        build(p,s,points);drain(p,s,s.loop.event.getList("DeliveryBuild",10).size());s.loop.story.remove("PreparedDeliveryRoute");return !s.loop.event.getBoolean("DeliveryBuildConflict");
    }
    /** Returns READY, PENDING or FAILED. Each tick expands at most 120 terrain cells. */
    static String tick(ServerPlayer p,VisitData.Scene s){var n=s.loop.event;if(n.contains("DeliveryBuild")){if(n.getBoolean("PlanningOnly"))return "READY";drain(p,s,96);if(n.getBoolean("DeliveryBuildConflict"))return "FAILED";if(n.getInt("DeliveryBuildCursor")<n.getList("DeliveryBuild",10).size())return "PENDING";for(var at:nodes(s))if(p.serverLevel().getBlockState(at.below()).getCollisionShape(p.serverLevel(),at.below()).isEmpty()||!p.serverLevel().noCollision(new AABB(at.getX()+.18,at.getY(),at.getZ()+.18,at.getX()+.18+.64,at.getY()+1.9,at.getZ()+.82)))return "FAILED";return "READY";}
        var search=SEARCHES.get(p.getUUID());if(search==null){if(n.contains("RouteGoal"))search=new Search(BlockPos.of(n.getLong("RouteStart")),BlockPos.of(n.getLong("RouteGoal")));else if(!prepare(p,s))return "FAILED";else return "PENDING";SEARCHES.put(p.getUUID(),search);}var r=SecretWorld.realm(p);var l=p.serverLevel();
        for(int count=0;count<120&&!search.open.isEmpty();count++){var at=search.open.remove().at;if(++search.expanded>22000)break;if(at.equals(search.goal)){var path=new ArrayList<BlockPos>();var q=at;while(!q.equals(search.start)){path.add(q);q=search.back.get(q);}path.add(search.start);Collections.reverse(path);if(path.stream().anyMatch(node->!OutingSites.feet(l,node)||!OutingSites.copied(r,node)||SecretDialogue.secretArea(s.loop.secrets,node))||!cottageSpace(l,r,s,house(s))){SEARCHES.remove(p.getUUID());n.remove("RouteGoal");n.remove("DeliveryHouse");return "PENDING";}n.putLongArray("DeliveryRoute",path.stream().mapToLong(BlockPos::asLong).toArray());SEARCHES.remove(p.getUUID());if(!n.getBoolean("PlanningOnly"))EventChunks.hold(p,s,path);build(p,s,path);return "PENDING";}
            for(var direction:Direction.Plane.HORIZONTAL)for(int dy:new int[]{0,1,-1}){var next=at.relative(direction).above(dy);if(!l.hasChunkAt(next)||!OutingSites.copied(r,next)||!OutingSites.feet(l,next)||(OtherWorldEstate.outsideDistance(r.house,next)>12&&!OutingSites.natural(l,next))||SecretDialogue.secretArea(s.loop.secrets,next)||next.distSqr(search.start)>400*400)continue;if(dy==1&&!l.noCollision(new AABB(at.getX()+.18,at.getY()+1,at.getZ()+.18,at.getX()+.82,at.getY()+2.9,at.getZ()+.82)))continue;double cost=search.cost.get(at)+1+Math.abs(dy)*1.2;if(cost>=search.cost.getOrDefault(next,Double.MAX_VALUE))continue;search.cost.put(next,cost);search.back.put(next,at);search.open.add(new Step(next,cost+Math.abs(next.getX()-search.goal.getX())+Math.abs(next.getZ()-search.goal.getZ())));break;}
        }if(search.open.isEmpty()||search.expanded>22000){SEARCHES.remove(p.getUUID());n.remove("RouteGoal");n.remove("DeliveryHouse");return n.getInt("RouteAttempt")>=18?"FAILED":"PENDING";}return "PENDING";
    }
    private static void cell(CompoundTag queue,BlockPos p,BlockState state){queue.put(Long.toString(p.asLong()),NbtUtils.writeBlockState(state));}
    static void build(ServerPlayer p,VisitData.Scene s,List<BlockPos> path){var n=s.loop.event;var queue=new CompoundTag();var l=p.serverLevel();var c=house(s);int style=Math.floorMod((int)n.getLong("DeliverySeed"),3);Block wall=style==0?Blocks.CHERRY_PLANKS:style==1?Blocks.SPRUCE_PLANKS:Blocks.STONE_BRICKS;
        for(int i=0;i<path.size();i++){var at=path.get(i);var original=l.getBlockState(at.below());if(OutingSites.natural(l,at)){Block mat=i%11==0?Blocks.MOSSY_COBBLESTONE:i%5==0?Blocks.COARSE_DIRT:l.getBlockState(at.below(2)).isFaceSturdy(l,at.below(2),Direction.UP)?Blocks.GRAVEL:Blocks.COARSE_DIRT;cell(queue,at.below(),mat.defaultBlockState());}if(i%18==10){var side=at.east(2);if(OutingSites.feet(l,side)&&OutingSites.natural(l,side)){cell(queue,side,Blocks.OAK_FENCE.defaultBlockState());cell(queue,side.above(),Blocks.LANTERN.defaultBlockState());}}
            if(i>0&&at.getY()>path.get(i-1).getY()&&OutingSites.natural(l,at)){var previous=path.get(i-1);Direction direction=Direction.fromDelta(at.getX()-previous.getX(),0,at.getZ()-previous.getZ());if(direction!=null)cell(queue,at.below(),Blocks.COBBLESTONE_STAIRS.defaultBlockState().setValue(StairBlock.FACING,direction));}}
        for(int x=-4;x<=4;x++)for(int z=-4;z<=4;z++){for(int y=-3;y<-1;y++)if(l.getBlockState(c.offset(x,y,z)).isAir())cell(queue,c.offset(x,y,z),Blocks.DIRT.defaultBlockState());cell(queue,c.offset(x,-1,z),Blocks.OAK_PLANKS.defaultBlockState());for(int y=0;y<=4;y++){boolean edge=Math.abs(x)==4||Math.abs(z)==4;Block block=edge?wall:Blocks.AIR;if(edge&&(y==1||y==2)&&(Math.abs(x)==4&&(z==-2||z==1)||Math.abs(z)==4&&(x==-2||x==2)))block=Blocks.GLASS;cell(queue,c.offset(x,y,z),block.defaultBlockState());}}
        for(int x=-5;x<=5;x++)for(int z=-5;z<=5;z++){int y=5+(5-Math.abs(x));cell(queue,c.offset(x,y,z),x==0?Blocks.DARK_OAK_PLANKS.defaultBlockState():Blocks.DARK_OAK_STAIRS.defaultBlockState().setValue(StairBlock.FACING,x<0?Direction.EAST:Direction.WEST));if(Math.abs(z)==4&&Math.abs(x)<=4)for(int fy=5;fy<y;fy++)cell(queue,c.offset(x,fy,z),wall.defaultBlockState());}
        for(int z=-6;z<=-5;z++)for(int x=-2;x<=2;x++)cell(queue,c.offset(x,-1,z),Blocks.SPRUCE_PLANKS.defaultBlockState());for(var half:DoubleBlockHalf.values())cell(queue,c.north(4).above(half==DoubleBlockHalf.UPPER?1:0),Blocks.SPRUCE_DOOR.defaultBlockState().setValue(DoorBlock.HALF,half).setValue(DoorBlock.FACING,Direction.NORTH));
        for(int x:new int[]{-3,3}){cell(queue,c.offset(x,0,-5),Blocks.OAK_FENCE.defaultBlockState());cell(queue,c.offset(x,1,-5),Blocks.LANTERN.defaultBlockState());cell(queue,c.offset(x,0,-6),Blocks.FLOWER_POT.defaultBlockState());}
        cell(queue,c.offset(4,0,-6),Blocks.OAK_FENCE.defaultBlockState());cell(queue,c.offset(4,1,-6),Blocks.POLISHED_ANDESITE_STAIRS.defaultBlockState().setValue(StairBlock.FACING,Direction.NORTH));cell(queue,c.offset(-2,0,2),Blocks.BOOKSHELF.defaultBlockState());cell(queue,c.offset(-1,0,2),Blocks.BOOKSHELF.defaultBlockState());cell(queue,c.offset(2,0,1),Blocks.SPRUCE_STAIRS.defaultBlockState().setValue(StairBlock.FACING,Direction.SOUTH));cell(queue,c.offset(2,0,2),Blocks.OAK_PLANKS.defaultBlockState());cell(queue,c.offset(2,1,2),Blocks.FLOWER_POT.defaultBlockState());cell(queue,c.offset(0,4,0),Blocks.LANTERN.defaultBlockState().setValue(LanternBlock.HANGING,true));
        // The three styles have distinct silhouettes/details, not only palette swaps.
        if(style==1)for(int x:new int[]{-4,4})for(int z:new int[]{-4,4})for(int y=0;y<=4;y++)cell(queue,c.offset(x,y,z),Blocks.SPRUCE_LOG.defaultBlockState());
        if(style==2){for(int y=0;y<10;y++)cell(queue,c.offset(3,y,3),Blocks.BRICKS.defaultBlockState());cell(queue,c.offset(3,10,3),Blocks.STONE_BRICK_SLAB.defaultBlockState());cell(queue,c.offset(3,0,2),Blocks.STONE_BRICK_STAIRS.defaultBlockState().setValue(StairBlock.FACING,Direction.NORTH));}
        if(style==0)for(int x:new int[]{-2,2}){cell(queue,c.offset(x,0,-5),Blocks.MOSS_BLOCK.defaultBlockState());cell(queue,c.offset(x,1,-5),Blocks.ALLIUM.defaultBlockState());cell(queue,c.offset(x,3,-4),Blocks.CHERRY_TRAPDOOR.defaultBlockState().setValue(TrapDoorBlock.FACING,Direction.NORTH).setValue(TrapDoorBlock.OPEN,true));}
        for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)cell(queue,c.offset(x,0,z),Blocks.PURPLE_CARPET.defaultBlockState());
        var list=new ListTag();for(String key:queue.getAllKeys()){var at=BlockPos.of(Long.parseLong(key));var original=l.getBlockState(at);if(original.hasBlockEntity())continue;var entry=new CompoundTag();entry.putLong("Pos",at.asLong());entry.put("Original",NbtUtils.writeBlockState(original));entry.put("Placed",queue.getCompound(key));list.add(entry);}n.put("DeliveryBuild",list);n.putInt("DeliveryBuildCursor",0);OtherMotherLoop.changed(p);
    }
    private static void drain(ServerPlayer p,VisitData.Scene s,int budget){var n=s.loop.event;var list=n.getList("DeliveryBuild",10);int cursor=n.getInt("DeliveryBuildCursor");var lookup=p.serverLevel().holderLookup(Registries.BLOCK);for(int i=0;i<budget&&cursor<list.size();i++){var entry=list.getCompound(cursor++);var at=BlockPos.of(entry.getLong("Pos"));if(p.serverLevel().getBlockState(at).equals(NbtUtils.readBlockState(lookup,entry.getCompound("Original"))))p.serverLevel().setBlock(at,NbtUtils.readBlockState(lookup,entry.getCompound("Placed")),2);else {n.putBoolean("DeliveryBuildConflict",true);n.putLong("DeliveryConflictPosition",at.asLong());n.putString("DeliveryConflictActual",p.serverLevel().getBlockState(at).toString());}}n.putInt("DeliveryBuildCursor",cursor);}
    static void cleanup(ServerPlayer p,VisitData.Scene s){SEARCHES.remove(p.getUUID());var l=p.server.getLevel(OtherWorld.KEY);if(l==null)return;var lookup=l.holderLookup(Registries.BLOCK);var n=s.loop.event;int cursor=n.getInt("DeliveryBuildCursor");var list=n.getList("DeliveryBuild",10);for(int i=0;i<Math.min(cursor,list.size());i++){var entry=list.getCompound(i);var at=BlockPos.of(entry.getLong("Pos"));if(l.getBlockState(at).equals(NbtUtils.readBlockState(lookup,entry.getCompound("Placed")))){l.removeBlockEntity(at);l.setBlock(at,NbtUtils.readBlockState(lookup,entry.getCompound("Original")),2);}}for(String key:List.of("DeliveryBuild","DeliveryBuildCursor","DeliveryBuildConflict","DeliveryConflictPosition","DeliveryConflictActual","DeliveryHouse","DeliveryRoute","RouteStart","RouteGoal","RouteAttempt"))n.remove(key);}
    static void clearSearches(){SEARCHES.clear();}
    private DeliveryRoute(){}
}
